import {materialPrice} from './realism.js';
export const MATERIALS={pla:{name:'PLA',price:24,color:'#d77e58'},petg:{name:'PETG',price:28,color:'#91a7a3'}};
export const FILAMENT_COLORS=[{id:'natural',name:'Blanc naturel',hex:'#ede5d3'},{id:'black',name:'Noir',hex:'#39423e'},{id:'terracotta',name:'Terracotta',hex:'#d67855'},{id:'sage',name:'Sauge',hex:'#8ca995'},{id:'lilac',name:'Lilas',hex:'#a1a2bd'},{id:'honey',name:'Miel',hex:'#dfb86f'},{id:'clay',name:'Argile',hex:'#b98970'},{id:'celadon',name:'Céladon',hex:'#8caba8'},{id:'ochre',name:'Ocre',hex:'#d1ab67'},{id:'plum',name:'Prune',hex:'#b399b6'}];
export const colorFor=id=>FILAMENT_COLORS.find(c=>c.id===id)||{id:'legacy',name:'Couleur libre · ancien stock',hex:'#d4bd98'};
export const colorFromHex=hex=>FILAMENT_COLORS.find(c=>c.hex===hex)?.id||'terracotta';
export function syncInventory(s){
 if(!Array.isArray(s.inventory))s.inventory=[];
 for(const material of Object.keys(MATERIALS)){let total=s.inventory.filter(l=>l.material===material).reduce((n,l)=>n+l.grams,0),difference=(s.stock[material]||0)-total;if(difference>.001)s.inventory.push({id:'lot-'+s.nextId++,material,colorId:'legacy',grams:difference,unitPrice:MATERIALS[material].price});else if(difference<-.001){let remove=-difference;for(const lot of [...s.inventory].reverse().filter(l=>l.material===material)){const take=Math.min(remove,lot.grams);lot.grams-=take;remove-=take;if(remove<=0)break;}}}s.inventory=s.inventory.filter(l=>l.grams>.001);for(const lot of s.inventory)if(!Number.isFinite(lot.unitPrice))lot.unitPrice=MATERIALS[lot.material].price;
}
export function filamentStock(s,material,colorId){syncInventory(s);return s.inventory.filter(l=>l.material===material&&(!colorId||l.colorId===colorId||l.colorId==='legacy')).reduce((a,l)=>a+l.grams,0);}
export function receiveFilament(s,material,colorId,qty,unitPrice=MATERIALS[material].price){for(let i=0;i<qty;i++)s.inventory.push({id:'lot-'+s.nextId++,material,colorId:colorId||'legacy',grams:1000,unitPrice});s.stock[material]+=qty*1000;}
export function consumeFilament(s,material,colorId,grams){if(filamentStock(s,material,colorId)+.001<grams)return false;let remaining=grams;const lots=s.inventory.filter(l=>l.material===material&&(l.colorId===colorId||l.colorId==='legacy')).sort((a,b)=>(a.colorId==='legacy')-(b.colorId==='legacy')||a.grams-b.grams);for(const lot of lots){const n=Math.min(remaining,lot.grams);lot.grams-=n;remaining-=n;if(remaining<=.001)break;}s.stock[material]=Math.max(0,s.stock[material]-grams);s.inventory=s.inventory.filter(l=>l.grams>.001);return true;}
export function stockNeeds(s){
 const groups=new Map();for(const o of s.orders.filter(o=>['design','queued','loading'].includes(o.status))){const colorId=o.colorId||colorFromHex(o.color),key=o.material+':'+colorId;if(!groups.has(key))groups.set(key,{material:o.material,colorId,grams:0});groups.get(key).grams+=o.grams;}
 const legacy={pla:filamentStock(s,'pla','legacy'),petg:filamentStock(s,'petg','legacy')};
 return [...groups.values()].map(n=>{const exact=s.inventory.filter(l=>l.material===n.material&&l.colorId===n.colorId).reduce((a,l)=>a+l.grams,0),use=Math.min(legacy[n.material],Math.max(0,n.grams-exact));legacy[n.material]-=use;const incoming=s.supplies.filter(l=>l.kind==='filament'&&l.item===n.material&&l.colorId===n.colorId).reduce((a,l)=>a+l.qty*1000,0);return {...n,available:exact+use,incoming,missing:Math.max(0,n.grams-exact-use-incoming)};});
}
export function quoteBasket(lines,settings={}){const combined=new Map();for(const l of lines||[]){if(!l||l.kind!=='filament'||!MATERIALS[l.item]||!FILAMENT_COLORS.some(c=>c.id===l.colorId)||!Number.isInteger(l.qty)||l.qty<1||l.qty>12)return {ok:false,message:'Référence ou quantité de bobines invalide.'};const key=l.item+':'+l.colorId,prev=combined.get(key);if(prev)prev.qty+=l.qty;else combined.set(key,{kind:'filament',item:l.item,colorId:l.colorId,qty:l.qty});}const normalized=[...combined.values()].map(l=>({...l,unitPrice:materialPrice(settings,l.item)})),qty=normalized.reduce((a,l)=>a+l.qty,0);if(!qty||qty>48)return {ok:false,message:'Choisis entre 1 et 48 bobines.'};const subtotal=normalized.reduce((a,l)=>a+l.unitPrice*l.qty,0);const shipping=settings.realism?.supplierShipping??4.9;return {ok:true,lines:normalized,qty,subtotal,shipping,total:subtotal+shipping,savedShipping:(qty-1)*shipping};}

export function filamentCost(s,material,colorId,grams){filamentStock(s,material,colorId);let remaining=grams,cost=0;const lots=s.inventory.filter(l=>l.material===material&&(l.colorId===colorId||l.colorId==='legacy')).sort((a,b)=>(a.colorId==='legacy')-(b.colorId==='legacy')||a.grams-b.grams);for(const lot of lots){const n=Math.min(remaining,lot.grams);cost+=n/1000*(lot.unitPrice??MATERIALS[material].price);remaining-=n;if(remaining<=.001)break;}return remaining>.001?null:cost;}
